public class Main {
    static int value(char c) {
        if (c == 'I') {
            return 1;
        } else if (c == 'V') {
            return 5;
        } else if (c == 'X') {
            return 10;
        } else if (c == 'L') {
            return 50;
        } else if (c == 'C') {
            return 100;
        } else if (c == 'D') {
            return 500;
        } else if (c == 'M') {
            return 1000;
        }
        return 0;
    }

    public static void main(String[] args) {
        String numeral = "XLII";
        int total = 0;
        for (int i = 0; i < numeral.length(); i++) {
            int current = value(numeral.charAt(i));
            if (i + 1 < numeral.length() && current < value(numeral.charAt(i + 1))) {
                total -= current;
            } else {
                total += current;
            }
        }
        System.out.println(total);
    }
}

